    internal partial class FishBinaryCreateTranslation : Fallout76MajorRecordBinaryCreateTranslation
    {
        public new static readonly FishBinaryCreateTranslation Instance = new FishBinaryCreateTranslation();

        public override RecordType RecordType => RecordTypes.FISH;
        public static ParseResult FillBinaryRecordTypes(
            IFishInternal item,
            MutagenFrame frame,
            PreviousParse lastParsed,
            Dictionary<RecordType, int>? recordParseCount,
            RecordType nextRecordType,
            int contentLength,
            TypedParseParams translationParams = default)
        {
            nextRecordType = translationParams.ConvertToStandard(nextRecordType);
            switch (nextRecordType.TypeInt)
            {
                case RecordTypeInts.EDID:
                {
                    if (!lastParsed.ParsedIndex.HasValue)
                    {
                        return Fallout76MajorRecordBinaryCreateTranslation.FillBinaryRecordTypes(
                            item: item,
                            frame: frame,
                            lastParsed: lastParsed,
                            recordParseCount: recordParseCount,
                            nextRecordType: nextRecordType,
                            contentLength: contentLength,
                            translationParams: translationParams.WithNoConverter());
                    }
                    else if (lastParsed.ParsedIndex.Value <= (int)MajorRecord_FieldIndex.EditorID)
                    {
                        frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                        item.EDID = StringBinaryTranslation.Instance.Parse(
                            reader: frame.SpawnWithLength(contentLength),
                            stringBinaryType: StringBinaryType.NullTerminate,
                            parseWhole: true);
                        return new ParseResult((int)Fish_FieldIndex.EDID, nextRecordType);
                    }
                    else
                    {
                        switch (recordParseCount?.GetOrAdd(nextRecordType) ?? 0)
                        {
                            case 0:
                                return Fallout76MajorRecordBinaryCreateTranslation.FillBinaryRecordTypes(
                                    item: item,
                                    frame: frame,
                                    lastParsed: lastParsed,
                                    recordParseCount: recordParseCount,
                                    nextRecordType: nextRecordType,
                                    contentLength: contentLength,
                                    translationParams: translationParams.WithNoConverter());
                            case 1:
                                frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                                item.EDID = StringBinaryTranslation.Instance.Parse(
                                    reader: frame.SpawnWithLength(contentLength),
                                    stringBinaryType: StringBinaryType.NullTerminate,
                                    parseWhole: true);
                                return new ParseResult((int)Fish_FieldIndex.EDID, nextRecordType);
                            default:
                                throw new NotImplementedException();
                        }
                    }
                }
                case RecordTypeInts.KSIZ:
                case RecordTypeInts.KWDA:
                {
                    item.Keywords = 
                        Mutagen.Bethesda.Plugins.Binary.Translations.ListBinaryTranslation<IFormLinkGetter<IKeywordGetter>>.Instance.Parse(
                            reader: frame,
                            countLengthLength: 4,
                            countRecord: translationParams.ConvertToCustom(RecordTypes.KSIZ),
                            triggeringRecord: translationParams.ConvertToCustom(RecordTypes.KWDA),
                            transl: FormLinkBinaryTranslation.Instance.Parse)
                        .CastExtendedList<IFormLinkGetter<IKeywordGetter>>();
                    return (int)Fish_FieldIndex.Keywords;
                }
                case RecordTypeInts.FISP:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.FISP = FloatBinaryTranslation<MutagenFrame, MutagenWriter>.Instance.Parse(reader: frame.SpawnWithLength(contentLength));
                    return (int)Fish_FieldIndex.FISP;
                }
                case RecordTypeInts.FIDS:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.FIDS = FloatBinaryTranslation<MutagenFrame, MutagenWriter>.Instance.Parse(reader: frame.SpawnWithLength(contentLength));
                    return (int)Fish_FieldIndex.FIDS;
                }
                case RecordTypeInts.FIES:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.FIES = FloatBinaryTranslation<MutagenFrame, MutagenWriter>.Instance.Parse(reader: frame.SpawnWithLength(contentLength));
                    return (int)Fish_FieldIndex.FIES;
                }
                case RecordTypeInts.FIHS:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.FIHS = frame.ReadUInt32();
                    return (int)Fish_FieldIndex.FIHS;
                }
                case RecordTypeInts.FILS:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.FILS = frame.ReadUInt32();
                    return (int)Fish_FieldIndex.FILS;
                }
                case RecordTypeInts.FIHD:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.FIHD = FloatBinaryTranslation<MutagenFrame, MutagenWriter>.Instance.Parse(reader: frame.SpawnWithLength(contentLength));
                    return (int)Fish_FieldIndex.FIHD;
                }
                case RecordTypeInts.FILD:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.FILD = FloatBinaryTranslation<MutagenFrame, MutagenWriter>.Instance.Parse(reader: frame.SpawnWithLength(contentLength));
                    return (int)Fish_FieldIndex.FILD;
                }
                case RecordTypeInts.FIJS:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.FIJS = FloatBinaryTranslation<MutagenFrame, MutagenWriter>.Instance.Parse(reader: frame.SpawnWithLength(contentLength));
                    return (int)Fish_FieldIndex.FIJS;
                }
                case RecordTypeInts.FIHJ:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.FIHJ = FloatBinaryTranslation<MutagenFrame, MutagenWriter>.Instance.Parse(reader: frame.SpawnWithLength(contentLength));
                    return (int)Fish_FieldIndex.FIHJ;
                }
                case RecordTypeInts.FILJ:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.FILJ = FloatBinaryTranslation<MutagenFrame, MutagenWriter>.Instance.Parse(reader: frame.SpawnWithLength(contentLength));
                    return (int)Fish_FieldIndex.FILJ;
                }
                case RecordTypeInts.FILA:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.FILA = FloatBinaryTranslation<MutagenFrame, MutagenWriter>.Instance.Parse(reader: frame.SpawnWithLength(contentLength));
                    return (int)Fish_FieldIndex.FILA;
                }
                case RecordTypeInts.FIHA:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.FIHA = FloatBinaryTranslation<MutagenFrame, MutagenWriter>.Instance.Parse(reader: frame.SpawnWithLength(contentLength));
                    return (int)Fish_FieldIndex.FIHA;
                }
                case RecordTypeInts.FIRI:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.FishItem.SetTo(FormLinkBinaryTranslation.Instance.Parse(reader: frame));
                    return (int)Fish_FieldIndex.FishItem;
                }
                case RecordTypeInts.FIEX:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.FishExplode.SetTo(FormLinkBinaryTranslation.Instance.Parse(reader: frame));
                    return (int)Fish_FieldIndex.FishExplode;
                }
                case RecordTypeInts.FISD:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.FishSound.SetTo(FormLinkBinaryTranslation.Instance.Parse(reader: frame));
                    return (int)Fish_FieldIndex.FishSound;
                }
                case RecordTypeInts.FISU:
                {
                    frame.Position += frame.MetaData.Constants.SubConstants.HeaderLength;
                    item.FishSurface.SetTo(FormLinkBinaryTranslation.Instance.Parse(reader: frame));
                    return (int)Fish_FieldIndex.FishSurface;
                }
                default:
                    return Fallout76MajorRecordBinaryCreateTranslation.FillBinaryRecordTypes(
                        item: item,
                        frame: frame,
                        lastParsed: lastParsed,
                        recordParseCount: recordParseCount,
                        nextRecordType: nextRecordType,
                        contentLength: contentLength,
                        translationParams: translationParams.WithNoConverter());
            }
        }

